"""Loss functions for training PeakCNN."""

import torch
import torch.nn.functional as F


def focal_loss(logits: torch.Tensor, targets: torch.Tensor, gamma: float) -> torch.Tensor:
    """Mean focal loss -(1 - p)^gamma * log(p), with p the predicted probability of the true class.

    gamma = 0 gives plain cross-entropy; larger gamma down-weights well-classified examples
    (Lin et al., "Focal Loss for Dense Object Detection", 2017).
    """
    log_p = F.log_softmax(logits, dim=1).gather(1, targets.unsqueeze(1)).squeeze(1)
    return (-(1.0 - log_p.exp()).pow(gamma) * log_p).mean()
